<?php
require_once __DIR__ . '/config/koneksi.php';
$statement = $pdo->prepare("SELECT judul, isi, gambar, tanggal_publikasi FROM berita WHERE slug = ? AND status = 'Terbit'");
$statement->execute([(string) ($_GET['slug'] ?? '')]);
$news = $statement->fetch();
if (!$news) { http_response_code(404); }
?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title><?= $news ? e($news['judul']) : 'Berita tidak ditemukan' ?></title><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Manrope:wght@400;500;600;700;800&display=swap" rel="stylesheet"><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css" rel="stylesheet"><link href="<?= e(base_url('assets/css/style.css')) ?>" rel="stylesheet"></head><body><?php require __DIR__ . '/includes/navbar.php'; ?><main class="detail-wrap"><div class="container"><a class="back-link" href="<?= e(base_url()) ?>#berita"><i class="fa-solid fa-arrow-left"></i> Kembali ke berita</a><?php if ($news): ?><article class="detail-content"><span class="eyebrow eyebrow-dark">KABAR LINGKUNGAN</span><h1><?= e($news['judul']) ?></h1><p class="detail-meta">Diterbitkan <?= e(format_tanggal($news['tanggal_publikasi'])) ?></p><?php if ($news['gambar']): ?><img class="detail-image" src="<?= e(base_url('uploads/berita/' . $news['gambar'])) ?>" alt="<?= e($news['judul']) ?>"><?php endif; ?><div class="article-text"><?= nl2br(e($news['isi'])) ?></div></article><?php else: ?><div class="empty-state">Berita tidak ditemukan.</div><?php endif; ?></div></main><?php require __DIR__ . '/includes/footer.php'; ?></body></html>